CREATE POLICY roles_super_read ON public.user_roles FOR SELECT TO authenticated USING(public.is_super_admin()); CREATE OR REPLACE FUNCTION public.mi_socio() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.socio_id FROM public.profiles p JOIN public.socios s ON s.id=p.socio_id WHERE p.id=auth.uid() AND s.estado='activa' AND (s.dispositivo_id=p.dispositivo_id OR public.is_directiva()) $$;